+    let bytes: [u8; 8] = value
+        .try_into()
+        .map_err(|_| JournalError::MalformedKeyspaceRow {
+            prefix: 0,
+            expected_len: 8,
+            actual_len: value.len(),
+        })?;
+    Ok(u64::from_be_bytes(bytes))
